235:     label = tools.length > 1 ? `正在${head}（${tools.length} 项）` : `正在${head}…`;
236:   } else if (tools.length === 1) {
237:     label = `已${head}`;
238:   } else if (actions.length === 1) {
239:     label = `已${head}（${tools.length} 次）`;
240:   } else {
241:     label = `已${head}（${tools.length} 项）`;
242:   }
243: 
244:   if (!running && failedCount > 0) {
245:     label += ` · ${failedCount} 项失败`;
246:   }
247:   return { label, running, failedCount };
248: }
249: 
250: /** 将单个运行期 ToolExecution 转为通用 TraceNode，供 ToolCall 卡片复用。 */
251: export function toolExecutionToTraceNode(
252:   tool: ToolExecution,
253:   resolveToolLabel?: (toolName: string) => string | undefined,
254: ): TraceNode {
255:   const running = tool.status === 'running';
256:   const failed = tool.status === 'failed';
257:   const status = running ? 'running' : failed ? 'failed' : 'completed';
258:   const isCommand =
259:     tool.toolName === 'execute_command' ||
260:     tool.toolName === 'execute' ||
261:     tool.toolName === 'terminal';
262: 
263:   if (isCommand) {
264:     return {
265:       id: tool.toolCallId,
266:       type: 'terminal',
267:       toolName: tool.toolName,
268:       primary: '运行',
269:       secondary: tool.command,
270:       command: tool.command,
271:       output: tool.output,
272:       exitCode: failed ? 1 : 0,
273:       status,
274:     };
275:   }
276: 
277:   const label = resolveToolLabel?.(tool.toolName);
278:   return {
279:     id: tool.toolCallId,
280:     type: 'tool',
281:     toolName: tool.toolName,
282:     primary: label || tool.toolName,
283:     secondary: tool.command || tool.toolName,
284:     command: tool.command,
285:     status,
286:     details: tool.output
287:       ? tool.output
288:           .split('\n')
289:           .filter(Boolean)
290:           .map((text) => ({ text, tone: (failed ? 'error' : 'muted') as 'error' | 'muted' }))
291:       : undefined,
292:   };
293: }
294: 
295: /** 格式化任务总耗时文案（如“用时 18 秒”或“用时 26分钟 18秒”）。 */
296: export function formatElapsedDuration(totalSeconds?: number): string {
297:   const safe = Math.max(0, Math.round(totalSeconds ?? 0));
298:   if (safe < 60) return `用时 ${safe} 秒`;
299:   const hours = Math.floor(safe / 3600);
300:   const minutes = Math.floor((safe % 3600) / 60);
301:   const seconds = safe % 60;
302:   if (hours > 0) {
303:     return seconds > 0
304:       ? `用时 ${hours}小时 ${minutes}分钟 ${seconds}秒`
305:       : `用时 ${hours}小时 ${minutes}分钟`;
306:   }
307:   return seconds > 0 ? `用时 ${minutes}分钟 ${seconds}秒` : `用时 ${minutes}分钟`;
308: }
309: 
310: /** 拆分为“前置过程链（思考、中间说明、工具组）”与“最终结论正文”，供结束后统一折叠过程链。 */
311: export function splitProcessAndFinalBlocks(blocks: MessageBlock[]): {
312:   processBlocks: MessageBlock[];
313:   finalTextBlock?: MessageBlock;
314: } {
315:   if (blocks.length === 0) return { processBlocks: [] };
316:   const hasProcess = blocks.some((b) => b.kind !== 'text') || blocks.length > 1;
317:   if (!hasProcess) {
318:     return { processBlocks: [], finalTextBlock: blocks[0] };
319:   }
320:   const last = blocks[blocks.length - 1];
321:   if (last.kind === 'text' && last.content?.trim()) {
322:     return {
323:       processBlocks: blocks.slice(0, -1),
324:       finalTextBlock: last,
325:     };
326:   }
327:   return { processBlocks: blocks };
328: }

