/// 与桌面端 `VendorIcon.tsx` 保持一致的厂商图标展示（匹配 `provider.type`）。
struct AgentVendorIconView: View {
    let vendor: String?
    let modelName: String?
    var size: CGFloat = 16

    private var vendorKey: String {
